49	// Abstraction representing an XLS Proc. Procs (from "processes") are stateful
50	// blocks which iterate indefinitely over mutable state of a fixed type. Procs
51	// communicate to other components via channels.
52	// TODO(meheff): Add link to documentation when we have some.
53	class Proc : public FunctionBase {
54	 public:
55	  // Creates a proc with no state elements.
56	  Proc(std::string_view name, Package* package)
57	      : FunctionBase(name, package), is_new_style_proc_(false) {}
58	
59	  // Creates a new-style proc which supports proc-scoped channels.
60	  Proc(std::string_view name,
61	       absl::Span<std::unique_ptr<ChannelInterface>> interface,
62	       Package* package)
63	      : FunctionBase(name, package), is_new_style_proc_(true) {
64	    for (std::unique_ptr<ChannelInterface>& channel_interface : interface) {
65	      channel_interfaces_.push_back(std::move(channel_interface));
66	      interface_.push_back(channel_interfaces_.back().get());
67	    }
68	  }
69	
70	  ~Proc() override = default;
71	
72	  void MoveFrom(Proc& other);
73	
74	  // Moves state, channels, and instantiations from `other`. Does not move any
75	  // logic, including state reads/writes.
76	  void MoveNonLogicFrom(Proc& other);
77	
78	  int64_t GetStateElementCount() const { return StateElements().size(); }
79	
80	  // Returns the total number of bits in the proc state.
81	  int64_t GetStateFlatBitCount() const;
82	
83	  // Returns the state element(s).
84	  absl::Span<StateElement* const> StateElements() const { return state_vec_; }
85	  StateElement* GetStateElement(int64_t index) const {
86	    return StateElements().at(index);
87	  }
88	  absl::StatusOr<StateElement*> GetStateElementByName(
89	      std::string_view name) const;
90	  std::optional<StateElement*> MaybeGetStateElementByName(
91	      std::string_view name) const;
92	
93	  bool HasStateElement(std::string_view name) const {
94	    return state_elements_.contains(name);
95	  }
96	
97	  // Remove legacy getters after all downstream passes migrate logic.
98	  StateRead* GetStateRead(int64_t index) const {
99	    absl::Span<StateRead* const> state_reads = GetStateReads(index);
100	    CHECK_EQ(state_reads.size(), 1);
101	    return state_reads.front();
102	  }
