111	  // Get state reads for a state element at the given index.
112	  absl::Span<StateRead* const> GetStateReads(int64_t index) const {
113	    return state_reads_.at(GetStateElement(index));
114	  }
115	
116	  // Get state reads for a state element.
117	  absl::Span<StateRead* const> GetStateReadsByStateElement(
118	      StateElement* state_element) const {
119	    auto it = state_reads_.find(state_element);
120	    if (it == state_reads_.end()) {
121	      return absl::Span<StateRead* const>();
122	    }
123	    return it->second;
124	  }
125	
126	  // Returns the index of the given state element in the vector of state
127	  // elements.
128	  absl::StatusOr<int64_t> GetStateElementIndex(
129	      StateElement* state_element) const;
130	  std::optional<int64_t> MaybeGetStateElementIndex(
131	      StateElement* state_element) const;
132	
133	  const Proc* GetEffectiveProcOrDie() const final { return this; }
134	
135	  Proc* GetEffectiveProcOrDie() final { return this; }
136	
137	  // Returns true if the given proc-scoped construct (state element) is owned by
138	  // this block.
139	  bool IsOwned(StateElement* reg) const {
140	    return state_elements_.contains(reg->name()) &&
141	           state_elements_.at(reg->name()).get() == reg;
142	  }
143	
144	  // Sanitizes and uniquifies the given name using the proc's name uniquer.
145	  // Registers the uniquified name in the state uniquer so it is not handed out
146	  // again.
147	  std::string UniquifyStateName(std::string_view name) {
148	    return state_name_uniquer_.GetSanitizedUniqueName(name);
149	  }
150	
151	  // Returns the type of the given state element.
152	  Type* GetStateElementType(int64_t index) const {
153	    return StateElements().at(index)->type();
154	  }
155	
156	  // A set of callbacks to help one replace a state element with one of a
157	  // different type.
158	  class StateElementTransformer {
159	   public:
160	    virtual ~StateElementTransformer() = default;
161	    // Called with the new_state_read node and the old state_read_node. Must
162	    // return a node which adapts the new_state_read's type to the
163	    // old_state_read's type.
164	    virtual absl::StatusOr<Node*> TransformStateRead(
165	        Proc* proc, StateRead* new_state_read, StateRead* old_state_read) {
166	      XLS_RET_CHECK(new_state_read->GetType() == old_state_read->GetType());
167	      return new_state_read;
168	    }
169	    // Called with the old state_read node. Must return a node which will be the
170	    // new 'predicate' for the new state_read. old_state_read's predicate.
171	    virtual absl::StatusOr<std::optional<Node*>> TransformReadPredicate(
172	        Proc* proc, StateRead* old_state_read) {
173	      return old_state_read->predicate();
174	    }
175	    // Called with the new_state_read node and the next-node (Without any
176	    // updates applied to it). Must return a node which adapts the old_next's
177	    // value() node to the value of the corresponding next on new_param.
178	    virtual absl::StatusOr<Node*> TransformNextValue(
179	        Proc* proc, StateElement* new_state_element, Next* old_next) {
180	      XLS_RET_CHECK(old_next->value()->GetType() == new_state_element->type());
181	      return old_next->value();
182	    }
183	    // Caled with the new_state_element and the next-node (Without any updates
184	    // applied to it). Must return a node which will be the new 'predicate' for
185	    // the corresponding 'next' on the new_state_element.
186	    virtual absl::StatusOr<std::optional<Node*>> TransformNextPredicate(
187	        Proc* proc, StateElement* new_state_element, Next* old_next) {
188	      return old_next->predicate();
189	    }
190	  };
191	
192	  // Transform the given state element using the 'transformer'. The new state
193	  // element will have the same name (though a different index) as the old one
194	  // and the type of 'init_value'. The callbacks in 'transform' will be called
195	  // to adapt everything to the new type.
196	  //
197	  // Once the transformer has fixed up the types ReplaceUsesWith will be used to
198	  // switch users of the old param to the new one.
199	  //
200	  // The old state element will continue to exist with a new name and all
201	  // identity next nodes with all users removed. It should be cleaned up by
202	  // ProcStateOptimizationPass in RemoveUnobservableStateElements.
203	  //
204	  // The proc must only use 'next' nodes to call this function.
205	  absl::StatusOr<StateElement*> TransformStateElement(
206	      StateElement* old_state_element, const Value& init_value,
207	      StateElementTransformer& transform);
208	
209	  // Remove the state element at the given index. All state elements higher than
210	  // `index` are shifted down one to fill the hole. The state parameter at the
211	  // index must have no uses.
212	  absl::Status RemoveStateElement(int64_t index);
213	
214	  // Remove all state elements currently present.
215	  absl::Status RemoveAllStateElements();
216	
217	  // Appends a state element with the given name (if possible), next state
218	  // value, and initial value. If `next_state` is not given then the next state
219	  // node for this state element is set to the newly created state parameter
220	  // node. Returns the newly created state read node.
221	  absl::StatusOr<StateRead*> AppendStateElement(
222	      std::string_view requested_state_name, const Value& init_value,
223	      std::optional<Node*> read_predicate, std::optional<Node*> next_state,
224	      bool non_synthesizable, const SourceInfo& loc = SourceInfo());
225	  absl::StatusOr<StateRead*> AppendStateElement(
226	      std::string_view requested_state_name, const Value& init_value,
227	      const SourceInfo& loc = SourceInfo()) {
228	    return AppendStateElement(requested_state_name, init_value,
229	                              /*read_predicate=*/std::nullopt,
230	                              /*next_state=*/std::nullopt,
231	                              /*non_synthesizable=*/false, loc);
232	  }
233	
234	  // Adds a state read node for an existing state element.
235	  absl::StatusOr<StateRead*> AddStateRead(
236	      StateElement* state_element,
237	      std::optional<Node*> predicate = std::nullopt,
238	      std::optional<std::string> label = std::nullopt,
239	      const SourceInfo& loc = SourceInfo());
240	
241	  // Add a new state element (at index) without any reads or nexts. These must
242	  // be added separately before verification.
243	  absl::StatusOr<StateElement*> InsertUnreadStateElement(
244	      int64_t index, std::string_view requested_state_name,
245	      const Value& init_value, bool non_synthesizable);
246	  absl::StatusOr<StateElement*> AppendUnreadStateElement(
247	      std::string_view requested_state_name, const Value& init_value,
248	      bool non_synthesizable, const SourceInfo& loc = SourceInfo()) {
249	    return InsertUnreadStateElement(GetStateElementCount(),
250	                                    requested_state_name, init_value,
251	                                    non_synthesizable);
252	  }
253	
254	  // Adds a state element at the given index. Current state elements at the
255	  // given index or higher will be shifted up. Returns the newly created
256	  // parameter node.
257	  absl::StatusOr<StateRead*> InsertStateElement(
258	      int64_t index, std::string_view requested_state_name,
259	      const Value& init_value, std::optional<Node*> read_predicate,
260	      std::optional<Node*> next_state, bool non_synthesizable,
261	      const SourceInfo& loc = SourceInfo());
262	  absl::StatusOr<StateRead*> InsertStateElement(
263	      int64_t index, std::string_view requested_state_name,
264	      const Value& init_value, const SourceInfo& loc = SourceInfo()) {
265	    return InsertStateElement(index, requested_state_name, init_value,
266	                              /*read_predicate=*/std::nullopt,
267	                              /*next_state=*/std::nullopt,
268	                              /*non_synthesizable=*/false, loc);
269	  }
270	
271	  bool HasImplicitUse(Node* node) const override;
272	
273	  // Creates a clone of the proc with the new name `new_name`. Proc is
274	  // owned by `target_package`. `channel_remapping` dictates how to map channel
275	  // names to new channel names in the cloned version; if a key is unavailable
276	  // in `channel_remapping` it is assumed to be the identity mapping at that
277	  // key.
278	  absl::StatusOr<Proc*> Clone(
279	      std::string_view new_name, Package* target_package = nullptr,
280	      const absl::flat_hash_map<std::string, std::string>& channel_remapping =
281	          {},
282	      const absl::flat_hash_map<const FunctionBase*, FunctionBase*>&
283	          call_remapping = {},
284	      const absl::flat_hash_map<std::string, std::string>&
285	          state_name_remapping = {},
286	      std::optional<absl::flat_hash_map<Node*, Node*>*> original_node_to_clone =
287	          std::nullopt,
288	      const absl::flat_hash_map<std::string, std::string>&
289	          spawned_proc_name_remapping = {}) const;
290	
291	  using FunctionBase::DumpIr;
292	  std::string DumpIr(const IrAnnotator& annotate) const override;
293	
294	  FunctionBase::Kind kind() const final { return FunctionBase::Kind::kProc; }
295	
296	  // Returns true if this is a new-style proc which has proc-scoped channels.
297	  bool is_new_style_proc() const { return is_new_style_proc_; }
298	
299	  // Returns the type of the channel reference (Channel or ChannelInterface)
300	  // with the given name.
301	  absl::StatusOr<Type*> GetChannelReferenceType(std::string_view name) const;
302	
303	  // Return the ordered list of the channel interfaces which form the interface
304	  // of the proc. Only can be called for new style procs.
305	  absl::Span<ChannelInterface* const> interface() const {
306	    CHECK(is_new_style_proc());
307	    return interface_;
308	  }
309	
310	  // Return the channels defined in this proc. Only can be called for new style
311	  // procs.
312	  absl::Span<Channel* const> channels() const {
313	    CHECK(is_new_style_proc());
314	    return channel_vec_;
315	  }
316	
317	  // Add a channel definition to the proc.  Only can be called for new style
318	  // procs. Returns a data structure holding pointers to the interfaces to the
319	  // two sides of the channel.
320	  absl::StatusOr<ChannelWithInterfaces> AddChannel(
321	      std::unique_ptr<Channel> channel);
322	
323	  // Remove a channel definition from the proc. Only can be called for new style
324	  // procs. Also removes the interfaces for the channel.
325	  absl::Status RemoveChannel(Channel* channel);
326	
327	  // Removes all channels and channel interfaces from this proc. Only can be
328	  // called for new style procs.
329	  absl::Status RemoveAllChannelsAndInterfaces();
330	
331	  // Returns the channel with the given name defined in the proc. Only can be
332	  // called for new style procs.
333	  absl::StatusOr<Channel*> GetChannel(std::string_view name);
334	
335	  // Returns whether a channel with the given name is declared in the proc. Only
336	  // can be called for new style procs.
337	  bool HasChannelWithName(std::string_view name);
338	
339	  // Returns the ChannelRef referring to the global channel or proc-scoped
340	  // channel (new-style procs) with the given name.
341	  absl::StatusOr<ChannelRef> GetChannelRef(std::string_view name,
342	                                           ChannelDirection direction);
343	
344	  bool ChannelIsOwnedByProc(Channel* channel);
345	
346	  // Add input/output channels to the interface of the proc.
347	  absl::StatusOr<ReceiveChannelInterface*> AddInputChannel(
348	      std::string_view name, Type* type, ChannelKind kind,
349	      FlowControl flow_control,
350	      std::optional<ChannelStrictness> strictness = std::nullopt);
351	  absl::StatusOr<SendChannelInterface*> AddOutputChannel(
352	      std::string_view name, Type* type, ChannelKind kind,
353	      FlowControl flow_control,
354	      std::optional<ChannelStrictness> strictness = std::nullopt);
355	  absl::StatusOr<ChannelInterface*> AddInterfaceChannel(
356	      std::string_view name, ChannelDirection direction, Type* type,
357	      ChannelKind kind, FlowControl flow_control,
358	      std::optional<ChannelStrictness> strictness = std::nullopt);
359	
360	  // Remove a channel from the interface of the proc. ChannelInterfaceslater
361	  // than `channel_interface` in the interface are shifted down.
362	  absl::Status RemoveChannelInterface(ChannelInterface* channel_interface);
363	
364	  // Returns true if the given ChannelInterface refers to an element on the
365	  // interface of the proc.
366	  bool IsOnProcInterface(ChannelInterface* channel_interface);
367	
368	  // Add an input/output channel to the interface of the proc. Only can be
369	  // called for new style procs.
370	  absl::StatusOr<ReceiveChannelInterface*> AddInputChannelInterface(
371	      std::unique_ptr<ReceiveChannelInterface> channel_interface);
372	  absl::StatusOr<SendChannelInterface*> AddOutputChannelInterface(
373	      std::unique_ptr<SendChannelInterface> channel_interface);
374	  absl::StatusOr<ChannelInterface*> AddChannelInterface(
375	      std::unique_ptr<ChannelInterface> channel_interface);
376	
377	  // Create and add a proc instantiation to the proc.
378	  absl::StatusOr<ProcInstantiation*> AddProcInstantiation(
379	      std::string_view name, absl::Span<ChannelInterface* const> channel_args,
380	      Proc* proc);
381	  // Delete all proc instantiations
382	  absl::StatusOr<std::vector<std::unique_ptr<ProcInstantiation>>>
383	  RemoveAllProcInstantiations();
384	
385	  // Returns whether this proc has a channel interface of the given name. Only
386	  // can be called for new style procs.
387	  bool HasChannelInterface(std::string_view name,
388	                           ChannelDirection direction) const;
389	
390	  // Returns the (Send/Receive) channel interface with the given name.
391	  absl::StatusOr<ChannelInterface*> GetChannelInterface(
392	      std::string_view name, ChannelDirection direction) const;
393	  absl::StatusOr<SendChannelInterface*> GetSendChannelInterface(
394	      std::string_view name) const;
395	  absl::StatusOr<ReceiveChannelInterface*> GetReceiveChannelInterface(
396	      std::string_view name) const;
397	
398	  // Returns all the channel interfaces in the proc. This includes interfaces on
399	  // the interface of the proc and of channels declared in the proc.
400	  absl::Span<const std::unique_ptr<ChannelInterface>> channel_interfaces()
401	      const {
402	    return channel_interfaces_;
403	  }
404	
405	  // Returns the list of instantiations of other procs in this proc.
406	  absl::Span<std::unique_ptr<ProcInstantiation>> proc_instantiations() {
407	    return absl::MakeSpan(proc_instantiations_);
408	  }
409	  absl::Span<const std::unique_ptr<ProcInstantiation>> proc_instantiations()
410	      const {
411	    return proc_instantiations_;
412	  }
413	
414	  absl::StatusOr<ProcInstantiation*> GetProcInstantiation(
415	      std::string_view instantiation_name) const;
416	
417	  // Sets the new-style proc bit to true. Proc may be malformed until the
418	  // interface and channel declarations are added.
419	  // TODO(https://github.com/google/xls/issues/869): Remove when all procs are
420	  // new-style.
421	  absl::Status ConvertToNewStyle();
422	
423	 protected:
424	  absl::Status InternalRebuildSideTables() final;
425	
426	 private:
427	  bool is_new_style_proc_;
428	
429	  NameUniquer state_name_uniquer_ =
430	      NameUniquer(/*separator=*/"__", GetIrReservedWords());
431	
432	  // State elements within this proc. Indexed by state element name. Stored as
433	  // std::unique_ptrs for pointer stability.
434	  absl::flat_hash_map<std::string, std::unique_ptr<StateElement>>
435	      state_elements_;
436	
437	  // Map of StateRead nodes for each state element.
438	  absl::flat_hash_map<StateElement*, std::vector<StateRead*>> state_reads_;
439	
440	  // Vector of state element pointers. Kept in sync with the state_elements_
441	  // map. Enables easy, stable iteration over state elements. With this vector,
442	  // deletion of a state element is O(n) with the number of state elements. If
443	  // this is a problem, a linked list might be used instead.
444	  std::vector<StateElement*> state_vec_;
445	
446	  // All channel interfaces in this proc. Channel interfaces can be part of the
447	  // proc interface or for channels declared in this proc.
448	  std::vector<std::unique_ptr<ChannelInterface>> channel_interfaces_;
449	
450	  // Channel interfaces which form interface of the proc.
451	  std::vector<ChannelInterface*> interface_;
452	
453	  // Instantiations of other procs within this proc.
454	  std::vector<std::unique_ptr<ProcInstantiation>> proc_instantiations_;
455	
456	  // Channels declared in this proc indexed by channel name.
457	  absl::flat_hash_map<std::string, std::unique_ptr<Channel>> channels_;
458	  std::vector<Channel*> channel_vec_;
459	};
460	
461	// A proc which has been scheduled and contains information about which nodes
462	// execute in which pipeline stage.
463	class ScheduledProc : public Proc {
464	 public:
465	  ScheduledProc(std::string_view name, Package* package)
466	      : Proc(name, package) {}
467	
468	  // Creates a new-style scheduled proc which supports proc-scoped channels.
469	  ScheduledProc(std::string_view name,
470	                absl::Span<std::unique_ptr<ChannelInterface>> interface,
471	                Package* package)
472	      : Proc(name, interface, package) {}
473	
474	  bool IsScheduled() const override { return true; }
475	
476	  // Creates a clone of the scheduled proc with the new name `new_name`. Proc is
477	  // owned by `target_package`. `channel_remapping` dictates how to map channel
478	  // names to new channel names in the cloned version; if a key is unavailable
479	  // in `channel_remapping` it is assumed to be the identity mapping at that
480	  // key.
481	  absl::StatusOr<ScheduledProc*> Clone(
482	      std::string_view new_name, Package* target_package = nullptr,
483	      const absl::flat_hash_map<std::string, std::string>& channel_remapping =
484	          {},
485	      const absl::flat_hash_map<const FunctionBase*, FunctionBase*>&
486	          call_remapping = {},
487	      const absl::flat_hash_map<std::string, std::string>&
488	          state_name_remapping = {}) const {
489	    XLS_ASSIGN_OR_RETURN(
490	        Proc * cloned_proc,
491	        Proc::Clone(new_name, target_package, channel_remapping, call_remapping,
492	                    state_name_remapping));
493	    return absl::down_cast<ScheduledProc*>(cloned_proc);
494	  }
495	};
