214	// Abstraction describing a channel in XLS IR. Channels are a mechanism for
215	// communicating between procs or between procs and components outside of
216	// XLS. Send and receive nodes in procs are associated with a particular
217	// channel. The channel data structure carries information about how
218	// communication occurs over the channel.
219	class Channel {
220	 public:
221	  virtual ~Channel() = default;
222	
223	  // Returns the name of the channel.
224	  std::string_view name() const { return name_; }
225	
226	  // Returns the ID of the channel. The ID is unique within the scope of a
227	  // package.
228	  int64_t id() const { return id_; }
229	
230	  // Returns the supported ops for the channel: send-only, receive-only, or
231	  // send-receive.
232	  ChannelOps supported_ops() const { return supported_ops_; }
233	
234	  Type* type() const { return type_; }
235	  absl::Span<const Value> initial_values() const { return initial_values_; }
236	
237	  // Returns whether this channel can be used to send (receive) data.
238	  bool CanSend() const {
239	    return supported_ops() == ChannelOps::kSendOnly ||
240	           supported_ops() == ChannelOps::kSendReceive;
241	  }
242	  bool CanReceive() const {
243	    return supported_ops() == ChannelOps::kReceiveOnly ||
244	           supported_ops() == ChannelOps::kSendReceive;
245	  }
246	
247	  ChannelKind kind() const { return kind_; }
248	
249	  virtual std::string ToString() const;
250	
251	  template <typename Sink>
252	  friend void AbslStringify(Sink& sink, const Channel& p) {
253	    absl::Format(&sink, "%s", p.name());
254	  }
255	
256	  // Comparators used for sorting by name/id.
257	  static bool NameLessThan(const Channel* a, const Channel* b) {
258	    return a->name() < b->name();
259	  }
260	  static bool IdLessThan(const Channel* a, const Channel* b) {
261	    return a->id() < b->id();
262	  }
263	
264	  // Struct form for passing comparators as template arguments.
265	  struct NameLessThan {
266	    bool operator()(const Channel* a, const Channel* b) const {
267	      return Channel::NameLessThan(a, b);
268	    }
269	  };
270	  struct IdLessThan {
271	    bool operator()(const Channel* a, const Channel* b) const {
272	      return Channel::IdLessThan(a, b);
273	    }
274	  };
275	
276	 protected:
277	  Channel(std::string_view name, int64_t id, ChannelOps supported_ops,
278	          ChannelKind kind, Type* type, absl::Span<const Value> initial_values)
279	      : name_(name),
280	        id_(id),
281	        supported_ops_(supported_ops),
282	        kind_(kind),
283	        type_(type),
284	        initial_values_(initial_values.begin(), initial_values.end()) {}
285	
286	  void SetName(std::string_view name) { name_ = name; }
287	
288	  std::string name_;
289	  int64_t id_;
290	  ChannelOps supported_ops_;
291	  ChannelKind kind_;
292	  Type* type_;
293	  std::vector<Value> initial_values_;
294	
295	  // For SetName;
296	  friend class Package;
297	};
298	
299	// The flow control mechanism to use for streaming channels. This affects how
300	// the channels are lowered to verilog.
301	enum class FlowControl : uint8_t {
302	  // The channel has no flow control. Some external mechanism ensures data is
303	  // neither lost nor corrupted.
304	  kNone,
305	
306	  // The channel uses a ready-valid handshake. A ready signal indicates the
307	  // receiver is ready to accept data, and a valid signal indicates the data
308	  // signal is valid. When both ready and valid are asserted a transaction
309	  // occurs.
310	  kReadyValid,
311	
312	  // The channel uses a valid-data handshake. A valid signal indicates that the
313	  // data is valid, and the receiver is presumed to always be ready to accept
314	  // data. A transaction occurs whenever valid is asserted.
315	  //
316	  // This is used when the channel doesn't want to support backpressure. Safe
317	  // use requires ensuring that the receiver can always accept data when the
318	  // sender is sending, and can optionally be checked with an assert.
319	  kValidData,
320	};
321	
322	inline constexpr FlowControl kDefaultChannelFlowControl =
323	    FlowControl::kReadyValid;
324	std::string FlowControlToString(FlowControl fc);
325	absl::StatusOr<FlowControl> StringToFlowControl(std::string_view str);
326	std::ostream& operator<<(std::ostream& os, FlowControl fc);
327	
328	// When multiple of the same channel operations happen on the same channel,
329	// scheduling legalizes them through a combination of:
330	//  1. Requiring proven properties of the channel operations.
331	//  2. Runtime checks (assertions) that properties of the channel are true.
332	//  3. Arbitrary selection of priority between operations.
333	//
334	// Note that this does not apply to e.g. a send and receive on an internal
335	// SendReceive channel. This only applies when multiples of the same channel
336	// operation are being performed on the same channel.
337	enum class ChannelStrictness : uint8_t {
338	  // Requires that channel operations be formally proven to be mutually
339	  // exclusive by Z3.
340	  kProvenMutuallyExclusive,
341	  // Requires that channel operations be mutually exclusive- enforced during
342	  // simulation via assertions.
343	  kRuntimeMutuallyExclusive,
344	  // For each proc, requires a total order on all operations on a channel. Note:
345	  // operations from different procs will not be ordered with respect to each
346	  // other.
347	  kTotalOrder,
348	  // Requires that a total order exists on every subset of channel operations
349	  // that fires at runtime. Adds assertions.
350	  kRuntimeOrdered,
351	  // For each proc, an arbitrary (respecting existing token relationships)
352	  // static priority is chosen for multiple channel operations. Operations
353	  // coming from different procs must be mutually exclusive (enforced via
354	  // assertions).
355	  kArbitraryStaticOrder,
356	};
357	
358	inline constexpr ChannelStrictness kDefaultChannelStrictness =
359	    ChannelStrictness::kProvenMutuallyExclusive;
360	
361	absl::StatusOr<ChannelStrictness> ChannelStrictnessFromString(
362	    std::string_view text);
363	std::string ChannelStrictnessToString(ChannelStrictness in);
364	std::ostream& operator<<(std::ostream& os, ChannelStrictness in);
365	
366	inline bool AbslParseFlag(std::string_view text, ChannelStrictness* result,
367	                          std::string* error) {
368	  absl::StatusOr<ChannelStrictness> channel_strictness =
369	      ChannelStrictnessFromString(text);
370	  if (channel_strictness.ok()) {
371	    *result = *std::move(channel_strictness);
372	    return true;
373	  }
374	  *error = channel_strictness.status().ToString();
375	  return false;
376	}
377	
378	inline std::string AbslUnparseFlag(
379	    const ChannelStrictness& channel_strictness) {
380	  return ChannelStrictnessToString(channel_strictness);
381	}
382	
383	// A channel with FIFO semantics. Send operations add an data entry to the
384	// channel; receives remove an element from the channel with FIFO ordering.
385	class StreamingChannel final : public Channel {
386	 public:
387	  StreamingChannel(std::string_view name, int64_t id, ChannelOps supported_ops,
388	                   Type* type, absl::Span<const Value> initial_values,
389	                   ChannelConfig channel_config, FlowControl flow_control,
390	                   ChannelStrictness strictness)
391	      : Channel(name, id, supported_ops, ChannelKind::kStreaming, type,
392	                initial_values),
393	        channel_config_(std::move(channel_config)),
394	        flow_control_(flow_control),
395	        strictness_(strictness) {}
396	
397	  std::optional<int64_t> GetFifoDepth() const {
398	    if (channel_config_.fifo_config()) {
399	      return channel_config_.fifo_config()->depth();
400	    }
401	    return std::nullopt;
402	  }
403	
404	  const ChannelConfig& channel_config() const { return channel_config_; }
405	  void SetChannelConfig(ChannelConfig value) { channel_config_ = value; }
406	
407	  FlowControl flow_control() const { return flow_control_; }
408	  void SetFlowControl(FlowControl value) { flow_control_ = value; }
409	
410	  ChannelStrictness strictness() const { return strictness_; }
411	  void SetStrictness(ChannelStrictness value) { strictness_ = value; }
412	
413	 private:
414	  ChannelConfig channel_config_;
415	  FlowControl flow_control_;
416	  ChannelStrictness strictness_;
417	};
418	
419	// A channel which holds a single value. Values are written to the channel via
420	// send operations, and receives nondestructively read the most-recently sent
421	// value. SingleValueChannels are stateless and do not support initial values.
422	class SingleValueChannel final : public Channel {
423	 public:
424	  SingleValueChannel(std::string_view name, int64_t id,
425	                     ChannelOps supported_ops, Type* type)
426	      : Channel(name, id, supported_ops, ChannelKind::kSingleValue, type,
427	                /*initial_values=*/{}) {}
428	};
429	
430	inline std::ostream& operator<<(std::ostream& os, const Channel* channel) {
431	  os << (channel == nullptr ? std::string("<nullptr Channel*>")
432	                            : channel->name());
433	  return os;
434	}
435	
436	enum class ChannelDirection : int8_t { kSend, kReceive };
437	
438	std::string ChannelDirectionToString(ChannelDirection direction);
439	absl::StatusOr<ChannelDirection> ChannelDirectionFromString(
440	    std::string_view str);
441	std::ostream& operator<<(std::ostream& os, ChannelDirection direction);
442	inline ChannelDirection InvertChannelDirection(ChannelDirection d) {
443	  switch (d) {
444	    case ChannelDirection::kSend:
445	      return ChannelDirection::kReceive;
446	    case ChannelDirection::kReceive:
447	      return ChannelDirection::kSend;
448	  }
449	}
450	
451	// Abstraction representing an interface to a channel. The interface can be
452	// typed to refer to the send or receive side. With proc-scoped channels (new
453	// style procs), channel-using operations such as send/receive refer to
454	// channel interfaces rather than channel objects. In elaboration these
455	// channel interfaces are bound to channel objects.
456	//
457	// TODO(https://github.com/google/xls/issues/869): Reconsider whether channel
458	// kind and strictness should be held by the channel interface. This is required
459	// for storing these properties on the interface of new-style procs. An
460	// alternative would be to have a separate data structure for interface
461	// channels.
462	class ChannelInterface {
463	 public:
464	  ChannelInterface(std::string_view name, Type* type, ChannelKind kind)
465	      : name_(name),
466	        type_(type),
467	        kind_(kind),
468	        strictness_(std::nullopt),
469	        flow_control_(FlowControl::kNone),
470	        flop_kind_(FlopKind::kNone) {}
471	  virtual ~ChannelInterface() = default;
472	
473	  // Like most IR constructs, ChannelInterfaces are passed around by pointer
474	  // and are not copyable.
475	  ChannelInterface(const ChannelInterface&) = delete;
476	  ChannelInterface& operator=(const ChannelInterface&) = delete;
477	
478	  std::string_view name() const { return name_; }
479	  Type* type() const { return type_; }
480	
481	  // TODO(meheff): Remove kind from ChannelInterface. This is a property of the
482	  // channel not the interface.
483	  void SetKind(ChannelKind value) { kind_ = value; }
484	  ChannelKind kind() const { return kind_; }
485	
486	  void SetStrictness(std::optional<ChannelStrictness> value) {
487	    strictness_ = value;
488	  }
489	  std::optional<ChannelStrictness> strictness() const { return strictness_; }
490	
491	  void SetFlowControl(FlowControl value) { flow_control_ = value; }
492	  FlowControl flow_control() const { return flow_control_; }
493	
494	  void SetFlopKind(FlopKind value) { flop_kind_ = value; }
495	  FlopKind flop_kind() const { return flop_kind_; }
496	
497	  virtual ChannelDirection direction() const = 0;
498	
499	  std::string ToString() const;
500	
501	  static bool NameLessThan(const ChannelInterface* a,
502	                           const ChannelInterface* b) {
503	    return a->name() < b->name();
504	  }
505	
506	  struct NameLessThan {
507	    bool operator()(const ChannelInterface* a,
508	                    const ChannelInterface* b) const {
509	      return ChannelInterface::NameLessThan(a, b);
510	    }
511	  };
512	
513	 private:
514	  std::string name_;
515	  Type* type_;
516	  ChannelKind kind_;
517	  std::optional<ChannelStrictness> strictness_;
518	  FlowControl flow_control_;
519	  FlopKind flop_kind_;
520	};
521	
522	class SendChannelInterface : public ChannelInterface {
523	 public:
524	  SendChannelInterface(std::string_view name, Type* type,
525	                       ChannelKind kind = ChannelKind::kStreaming)
526	      : ChannelInterface(name, type, kind) {}
527	  ~SendChannelInterface() override = default;
528	  std::unique_ptr<SendChannelInterface> Clone(
529	      std::optional<std::string_view> new_name = std::nullopt,
530	      Type* new_ty = nullptr) const;
531	  ChannelDirection direction() const override {
532	    return ChannelDirection::kSend;
533	  }
534	};
535	
536	class ReceiveChannelInterface : public ChannelInterface {
537	 public:
538	  ReceiveChannelInterface(std::string_view name, Type* type,
539	                          ChannelKind kind = ChannelKind::kStreaming)
540	      : ChannelInterface(name, type, kind) {}
541	  ~ReceiveChannelInterface() override = default;
542	  std::unique_ptr<ReceiveChannelInterface> Clone(
543	      std::optional<std::string_view> new_name = std::nullopt,
544	      Type* new_ty = nullptr) const;
545	  ChannelDirection direction() const override {
546	    return ChannelDirection::kReceive;
547	  }
548	};
549	
550	// Abstraction gathering a channel with send and receive interfaces.
551	struct ChannelWithInterfaces {
552	  Channel* channel;
553	  SendChannelInterface* send_interface;
554	  ReceiveChannelInterface* receive_interface;
555	};
556	
557	// Type which holds a channel or channel reference. This is a type used to
558	// transition to proc-scoped channels. In the proc-scoped channel universe all
559	// uses of channels use ChannelInterfaces rather than Channel objects.
560	// TODO(https://github.com/google/xls/issues/869): Remove these and replace
561	// with ChannelInterface* when all procs are new style.
562	using ChannelRef = std::variant<Channel*, ChannelInterface*>;
563	using SendChannelRef = std::variant<Channel*, SendChannelInterface*>;
564	using ReceiveChannelRef = std::variant<Channel*, ReceiveChannelInterface*>;
565	
566	using AnyChannelRef =
567	    std::variant<ChannelRef, SendChannelRef, ReceiveChannelRef>;
568	
569	// Return the name/type/kind/etc of a channel reference.
570	std::string_view ChannelRefName(ChannelRef ref);
571	Type* ChannelRefType(ChannelRef ref);
572	ChannelKind ChannelRefKind(ChannelRef ref);
573	std::optional<ChannelStrictness> ChannelRefStrictness(ChannelRef ref);
574	FlowControl ChannelRefFlowControl(ChannelRef ref);
575	
576	std::string ChannelRefToString(ChannelRef ref);
577	
578	ChannelRef ToChannelRef(AnyChannelRef ref);
579	
580	inline std::string_view ChannelRefName(AnyChannelRef ref) {
581	  return ChannelRefName(ToChannelRef(ref));
582	}
583	inline Type* ChannelRefType(AnyChannelRef ref) {
584	  return ChannelRefType(ToChannelRef(ref));
585	}
586	inline ChannelKind ChannelRefKind(AnyChannelRef ref) {
587	  return ChannelRefKind(ToChannelRef(ref));
588	}
589	inline std::optional<ChannelStrictness> ChannelRefStrictness(
590	    AnyChannelRef ref) {
591	  return ChannelRefStrictness(ToChannelRef(ref));
592	}
593	inline FlowControl ChannelRefFlowControl(AnyChannelRef ref) {
594	  return ChannelRefFlowControl(ToChannelRef(ref));
595	}
596	
597	inline std::string ChannelRefToString(AnyChannelRef ref) {
598	  return ChannelRefToString(ToChannelRef(ref));
599	}
